insert into public.t3a_event_name_alias (alias, dictionary_version, event_name, confidence, note) values
  ('observation_committed', '1.3', 'observation.committed', 'package', 'Named in 7.2. Written by t3a_commit_observation'),
  ('progression_recorded', '1.3', 'observation.progression_recorded', 'package', 'Named in 7.2'),
  ('observation_path_gateway_opened', '1.3', 'observation.path_opened', 'direct', 'Written by t3a_create_observation_path_gateway'),
  ('stage_entry_event_opened', '1.3', 'observation.stage_entered', 'direct', 'Written by t3a_create_stage_entry_event'),
  ('s1_observation_confirmed', '1.3', 'observation.s1_confirmed', 'direct', 'Written by t3a_confirm_s1_observation'),
  ('progression_decision_recorded', '1.3', 'observation.progression_recorded', 'direct', 'Written by t3a_record_progression_decision'),
  ('challenge_opened', '1.3', 'challenge.opened', 'direct', 'Written by t3a_open_challenge'),
  ('disclosure_created', '1.3', 'release.recipient_created', 'provisional', 'Named recipient release; the D2/D3 editions (D-04) retire this route. Written by t3a_create_disclosure'),
  ('disclosure_revoked', '1.3', 'release.changed', 'provisional', 'Named recipient release, see above. Written by t3a_revoke_disclosure'),
  ('question_set_ratified', '1.3', 'registry.version_approved', 'provisional', 'Ratifying a question set is a registry version approval. Written by t3a_ratify_question_set')
on conflict (alias) do nothing;

