  ('ber_report_id', 't3a_d1_ber_report', 'ber_report_id', null)
on conflict (payload_key) do nothing;

do $$
declare n_events integer; n_active integer; n_dormant integer; n_socket integer;
begin
  select count(*), count(*) filter (where status='ACTIVE'), count(*) filter (where status='DORMANT'), count(*) filter (where status='SOCKET')
    into n_events, n_active, n_dormant, n_socket from public.t3a_event_registry where dictionary_version = '1.3';
  if n_events <> 122 then
    raise exception 'T3A_EVENT_REGISTRY_LOAD_MISMATCH: expected 122 events, found %', n_events;
  end if;
  raise notice 'event registry 1.3 loaded: % events (% ACTIVE, % DORMANT, % SOCKET)', n_events, n_active, n_dormant, n_socket;
end $$;
